  "nsf": { title: "NSF", body: "Non-Stop Forwarding؛ تداوم Forwarding در زمان Failover Control Plane." },
  "glbp": { title: "GLBP", body: "Gateway Load Balancing Protocol؛ FHRP اختصاصی سیسکو با قابلیت Load Balancing بین چند روتر." },
  "spine-leaf": { title: "Spine-Leaf", body: "معماری Data Center مدرن؛ هر Leaf به همه Spineها وصل است — Latency یکنواخت و مقیاس‌پذیری افقی." },
  "vtip": { title: "VTEP", body: "VXLAN Tunnel Endpoint؛ دستگاهی که Encapsulation/Decapsulation VXLAN را انجام می‌دهد." },
  "vni": { title: "VNI", body: "VXLAN Network Identifier؛ شناسه ۲۴ بیتی معادل VLAN ID در VXLAN — ~۱۶ میلیون Segment." },
  "eid": { title: "EID", body: "Endpoint ID در LISP؛ هویت دستگاه (مثل IP هاست)." },
  "rloc": { title: "RLOC", body: "Routing Locator در LISP؛ مکان فیزیکی دستگاه (مثل IP روتر)." },
