  "nbma": { title: "NBMA", body: "Non-Broadcast Multi-Access؛ نوع شبکه بدون Broadcast مثل Frame Relay." },
  "pim": { title: "PIM", body: "Protocol Independent Multicast؛ پروتکل Multicast Router-to-Router. دو حالت Sparse و Dense." },
