  "rp": { title: "RP", body: "Rendezvous Point؛ نقطه ملاقات Senderها و Receiverها در PIM Sparse Mode." },
  "llq": { title: "LLQ", body: "Low Latency Queuing؛ مکانیزم QoS با Priority Queue برای ترافیک حساس مثل VoIP." },
  "wred": { title: "WRED", body: "Weighted Random Early Detection؛ مکانیزم Congestion Avoidance در QoS." },
  "vmanage": { title: "vManage", body: "رابط گرافیکی مدیریت Cisco SD-WAN — Provision، Monitor، Troubleshoot." },
  "vbond": { title: "vBond", body: "Orchestrator در Cisco SD-WAN؛ احراز هویت اولیه Edgeها و معرفی به Controller." },
  "vsmart": { title: "vSmart", body: "Controller در Cisco SD-WAN؛ توزیع Policy و Routing Information." },
  "vtep-switch": { title: "Virtual Switch", body: "پل بین VMها و شبکه فیزیکی در Hypervisor — Standard یا Distributed." },
    // ---- اضافات فصل ۲ CCNP ----
  "hypervisor": { title: "Hypervisor", body: "لایه نرم‌افزاری مجازی‌سازی که به VMها اجازه اجرا روی یک سرور فیزیکی می‌دهد. Type 1 (Bare-Metal) و Type 2 (Hosted)." },
  "vm": { title: "VM", body: "Virtual Machine؛ کامپیوتر کامل مجازی با CPU، RAM، Disk و NIC مستقل." },
