  "vswitch": { title: "vSwitch", body: "سوئیچ نرم‌افزاری در Hypervisor که VMها را به شبکه فیزیکی و به هم وصل می‌کند." },
  "vrf-lite": { title: "VRF-Lite", body: "استفاده از VRF بدون MPLS؛ هر VRF جدول مسیریابی مستقل خودش را دارد." },
  "rd": { title: "RD (Route Distinguisher)", body: "شناسه ۶۴ بیتی که یکتایی Routeها را در VRFهای مختلف تضمین می‌کند." },
