  "ikev2": { title: "IKEv2", body: "نسخه مدرن IKE با ۴ پیام، MOBIKE و NAT-T داخلی — سریع‌تر و امن‌تر از IKEv1." },
  "transform-set": { title: "Transform Set", body: "تعریف الگوریتم‌های IPsec (Encryption + Hash) برای SA." },
  "crypto-map": { title: "Crypto Map", body: "روش سنتی اعمال IPsec روی اینترفیس با ACL Match — امروز با Tunnel Protection جایگزین می‌شود." },
