  "mobike": { title: "MOBIKE", body: "IKEv2 Mobility and Multihoming؛ قابلیت حفظ Session در زمان تغییر IP — فقط در IKEv2." },
    // ---- اضافات فصل ۳ CCNP ----
  "vtp": { title: "VTP", body: "Vlan Trunking Protocol؛ پروتکل اختصاصی سیسکو برای همگام‌سازی VLAN Database بین سوئیچ‌ها. سه Mode: Server، Client، Transparent." },
  "vtp-v3": { title: "VTPv3", body: "نسخه سوم VTP با Extended VLANs، Primary Server و Authentication قوی. جایگزین امن VTPv1/v2." },
