  "mstp": { title: "MSTP", body: "Multiple Spanning Tree Protocol (802.1s)؛ نگاشت چند VLAN به یک Instance، Load Balancing، Region با ۳ پارامتر یکسان." },
  "mst-instance": { title: "MST Instance", body: "MSTI؛ توپولوژی STP مجزا در MSTP که چند VLAN در آن قرار می‌گیرند." },
